solution.javascript:
function parGenerations(racine) {
  const resultat = [];
  let generation = [racine];
  while (generation.length > 0) {
    resultat.push(generation.map((membre) => membre.nom));
    const suivante = [];
    for (const membre of generation) {
      for (const enfant of membre.enfants) {
        suivante.push(enfant);
      }
    }
    generation = suivante;
  }
  return resultat;
}

