solution.javascript:
function cheminEntre(racine, depart, arrivee) {
  function depuisRacine(membre, cible) {
    if (membre.nom === cible) {
      return [cible];
    }
    for (const enfant of membre.enfants) {
      const sous = depuisRacine(enfant, cible);
      if (sous !== null) {
        return [membre.nom, ...sous];
      }
    }
    return null;
  }
  const haut = depuisRacine(racine, depart);
  const bas = depuisRacine(racine, arrivee);
  if (haut === null || bas === null) {
    return [];
  }
  let commun = 0;
  while (commun < haut.length && commun < bas.length && haut[commun] === bas[commun]) {
    commun = commun + 1;
  }
  const montee = haut.slice(commun - 1).reverse();
  return montee.concat(bas.slice(commun));
}

