def chemin_entre(racine, depart, arrivee):
    def depuis_racine(membre, cible):
        if membre["nom"] == cible:
            return [cible]
        for enfant in membre["enfants"]:
            sous = depuis_racine(enfant, cible)
            if sous is not None:
                return [membre["nom"]] + sous
        return None

    haut = depuis_racine(racine, depart)
    bas = depuis_racine(racine, arrivee)
    if haut is None or bas is None:
        return []
    commun = 0
    while commun < len(haut) and commun < len(bas) and haut[commun] == bas[commun]:
        commun = commun + 1
    montee = list(reversed(haut[commun - 1:]))
    return montee + bas[commun:]

